REMOVED_NAME = 'removed-{pk}'
BACKFILL_NOTE = '정지의 기록을 두기 전에 정지했다(#634)'


def record_existing_suspensions(apps, schema_editor) -> None:
    """지금 정지된 계정마다 풀리지 않은 정지를 한 줄 적는다. 정지한 때는 세션을 끊은 시각이다(정지가 끊는다)."""
    User = apps.get_model('accounts', 'User')
    Suspension = apps.get_model('accounts', 'Suspension')
    now = timezone.now()
    Suspension.objects.bulk_create(
        Suspension(user=user, reason='other', note=BACKFILL_NOTE, suspended_at=user.sessions_revoked_at or now)
        for user in User.objects.filter(is_active=False).only('pk', 'nickname', 'sessions_revoked_at')
        if user.nickname != REMOVED_NAME.format(pk=user.pk)
    )


